 let cards=store.get(),filters={query:'',category:'',tag:'',kind:''},randomFilters={query:'',category:'',tag:'',kind:''},viewMode='archive',page=0,session=null,dataSignature='',language='',applyingAction=false,editorClose=null;
 const G=window.ProcatsGeography,D=window.ProcatsDiscovery;
