 function rememberDiscovery(id){const s=session;if(s.marked===id)return;const next=D.mark(discoveryHistory(),id,cards.map(c=>c.id),{reset:s.resetBag,resetPool:s.pool});s.resetBag=false;s.marked=id;try{window.localStorage.setItem(discoveryKey,JSON.stringify(next));}catch{};}
