 const shell=el('div','kh-shell'),header=el('header','kh-header'),titleBlock=el('div'),eyebrow=el('div','kh-eyebrow'),title=el('h1'),sub=el('p','kh-muted'),topActions=el('div','kh-top-actions'),add=button('',()=>edit(), 'kh-button kh-primary'),help=button('?',()=>{const p=ProcatsFeatureUI.panel('knowledgeHelp',L('helpTitle'));p.content.append(el('p','kh-help',L('helpBody')),el('p','kh-muted',L('countHint')));});help.classList.add('kh-help-button');
