 const tools=el('div','kh-tools'),search=el('input','kh-search'),category=el('select'),tag=el('select'),kind=el('select');search.type='search';search.maxLength=200;search.oninput=()=>{activeFilters().query=search.value;page=0;session=null;renderBody();};
