 const stats=el('div','kh-stats'),body=el('div','kh-body'),status=el('div','kh-status');status.setAttribute('role','status');shell.append(header,tabs,tools,stats,body,status);root.append(shell);
 function filtered(){return C.filter(cards,activeFilters());}
 function notifyError(e){showCustomAlert(L(/changed|missing/.test(e.message)?'changed':/limit/.test(e.message)?'limit':'failed'));}
 function change(action){applyingAction=true;try{store.commit(C.update(store.get(),action));if(action.type==='save')page=0;return true;}catch(e){notifyError(e);return false;}finally{applyingAction=false;if(action.type!=='rate')renderBody();}}
 function options(select,values,current){select.replaceChildren();for(const [value,label]of values){const o=el('option','',label);o.value=value;select.append(o);}select.value=values.some(([v])=>v===current)?current:'';}
